package cn.binbin.crm;
import jakarta.validation.constraints.*;import java.util.*;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class KnowledgeService {
 public record CategoryInput(@NotBlank @Size(max=100) String name,UUID parentId,boolean active,@Min(0) long expectedVersion){}
 public record ArticleInput(@NotNull UUID categoryId,@NotBlank @Size(max=200) String title,@NotBlank @Size(max=20000) String body,@Min(0) long expectedVersion){}
 public record Decision(@Min(0) long expectedVersion,@Size(max=500) String reason){}
 public record Reference(@NotNull UUID articleId,@Min(0) long expectedVersion){}
 private final P3Base b;private final ServiceDeskService desk;public KnowledgeService(P3Base b,ServiceDeskService desk){this.b=b;this.desk=desk;}
 private boolean privileged(AuthService.Actor a,Map<String,Object> r){return a.p3Access().knowledgePublish()||a.tenant().memberId().equals(r.get("authorMemberId"));}
 private Map<String,Object> article(AuthService.Actor a,UUID id){if(!a.p3Access().knowledgeRead())throw ApiError.forbidden("没有知识读取权限");var r=b.one("SELECT k.*,m.display_name AS author_name,c.name AS category_name FROM crm_knowledge_article k JOIN sys_tenant_member m ON m.tenant_id=k.tenant_id AND m.id=k.author_member_id JOIN crm_knowledge_category c ON c.tenant_id=k.tenant_id AND c.id=k.category_id WHERE k.tenant_id=:tenant AND k.id=:id",map("tenant",a.tenant().id(),"id",id));boolean privileged=privileged(a,r);if(!privileged){if(r.get("publishedVersion")==null||"ARCHIVED".equals(r.get("status")))throw ApiError.missing();var snap=b.object(String.valueOf(b.one("SELECT snapshot::text AS value FROM crm_knowledge_revision WHERE tenant_id=:tenant AND article_id=:id AND business_version=:version",map("tenant",a.tenant().id(),"id",id,"version",r.get("publishedVersion"))).get("value")));snap.put("publishedVersion",r.get("publishedVersion"));r=snap;}r.put("canWrite",a.p3Access().knowledgeWrite()&&privileged&&"DRAFT".equals(r.get("status"))&&a.tenant().subscriptionEnd().isAfter(java.time.Instant.now()));r.put("canManage",a.p3Access().knowledgeWrite()&&privileged&&a.tenant().subscriptionEnd().isAfter(java.time.Instant.now()));r.put("canPublish",a.p3Access().knowledgePublish()&&"DRAFT".equals(r.get("status"))&&a.tenant().subscriptionEnd().isAfter(java.time.Instant.now()));return r;}
 public Object get(AuthService.Session s,UUID id){return b.scoped(s,"knowledge",false,a->article(a,id));}
 public Object categories(AuthService.Session s){return b.scoped(s,"knowledge",false,a->b.rows("SELECT * FROM crm_knowledge_category WHERE tenant_id=:tenant ORDER BY name,id",map("tenant",a.tenant().id())));}
 public Object category(AuthService.Session s,UUID id,CategoryInput i,String key,UUID trace){return b.scoped(s,"publish",true,a->{UUID selected=id==null?b.once(a,"knowledge.category",key,i,()->{UUID created=UUID.randomUUID();hierarchy(a,created,i.parentId());b.db.update("INSERT INTO crm_knowledge_category(id,tenant_id,name,parent_id,active) VALUES(:id,:tenant,:name,:parent,:active)",map("id",created,"tenant",a.tenant().id(),"name",text(i.name()),"parent",i.parentId(),"active",i.active()));b.audit(a,"KNOWLEDGE_CATEGORY_CREATED","KNOWLEDGE_CATEGORY",created,0,trace);return created;}):id;if(id!=null){hierarchy(a,id,i.parentId());if(!i.active()&&b.db.queryForObject("SELECT count(*) FROM crm_knowledge_category WHERE tenant_id=:tenant AND parent_id=:id AND active",map("tenant",a.tenant().id(),"id",id),Integer.class)>0)throw ApiError.conflict("先停用下级分类");int n=b.db.update("UPDATE crm_knowledge_category SET name=:name,parent_id=:parent,active=:active,version=version+1 WHERE tenant_id=:tenant AND id=:id AND version=:version",map("tenant",a.tenant().id(),"id",id,"name",text(i.name()),"parent",i.parentId(),"active",i.active(),"version",i.expectedVersion()));if(n!=1)throw ApiError.conflict("分类已变化");b.audit(a,"KNOWLEDGE_CATEGORY_UPDATED","KNOWLEDGE_CATEGORY",id,i.expectedVersion()+1,trace);}return b.one("SELECT * FROM crm_knowledge_category WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",selected));});}
 private void hierarchy(AuthService.Actor a,UUID id,UUID parent){var seen=new HashSet<UUID>();seen.add(id);for(UUID cur=parent;cur!=null;){if(!seen.add(cur)||seen.size()>16)throw ApiError.bad("分类不能循环，最多16层");var p=b.one("SELECT parent_id FROM crm_knowledge_category WHERE tenant_id=:tenant AND id=:id AND active",map("tenant",a.tenant().id(),"id",cur));cur=(UUID)p.get("parentId");}}
 public Object list(AuthService.Session s,int page,int size,String q,String state,UUID category){page(page,size,q);if(!Set.of("","DRAFT","PUBLISHED","ARCHIVED").contains(state))throw ApiError.bad("知识状态无效");return b.scoped(s,"knowledge",false,a->{var p=map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"publisher",a.p3Access().knowledgePublish(),"category",category,"state",state,"q",text(q).toLowerCase(Locale.ROOT));var ids=b.rows("SELECT k.id FROM crm_knowledge_article k WHERE k.tenant_id=:tenant AND(:publisher OR k.author_member_id=:member OR(k.published_version IS NOT NULL AND k.status<>'ARCHIVED')) ORDER BY k.updated_at DESC,k.id",p);var visible=new ArrayList<Map<String,Object>>();for(var row:ids){var r=article(a,(UUID)row.get("id"));if(category!=null&&!category.toString().equals(String.valueOf(r.get("categoryId"))))continue;if(!state.isEmpty()&&!state.equals(r.get("status")))continue;if(!text(String.valueOf(r.get("title"))).toLowerCase(Locale.ROOT).contains(text(q).toLowerCase(Locale.ROOT))&&!text(String.valueOf(r.get("body"))).toLowerCase(Locale.ROOT).contains(text(q).toLowerCase(Locale.ROOT)))continue;r.remove("body");visible.add(r);}long offset=((long)page-1)*size;return new BusinessService.Page<>(visible.subList((int)Math.min(offset,visible.size()),(int)Math.min(offset+size,visible.size())),page,size,visible.size());});}
 public Object save(AuthService.Session s,UUID id,ArticleInput i,String key,UUID trace){return b.scoped(s,"knowledge",true,a->{b.one("SELECT id FROM crm_knowledge_category WHERE tenant_id=:tenant AND id=:id AND active",map("tenant",a.tenant().id(),"id",i.categoryId()));UUID selected=id==null?b.once(a,"knowledge.create",key,i,()->{UUID created=UUID.randomUUID();b.db.update("INSERT INTO crm_knowledge_article(id,tenant_id,category_id,title,body,author_member_id) VALUES(:id,:tenant,:category,:title,:body,:member)",map("id",created,"tenant",a.tenant().id(),"category",i.categoryId(),"title",text(i.title()),"body",text(i.body()),"member",a.tenant().memberId()));revision(a,created,"CREATED","",trace);return created;}):id;if(id!=null){var r=article(a,id);if(!Boolean.TRUE.equals(r.get("canWrite")))throw ApiError.forbidden("先转回草稿，且需作者 / 发布经理权限");b.version(r,i.expectedVersion());b.db.update("UPDATE crm_knowledge_article SET title=:title,body=:body,category_id=:category,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",map("tenant",a.tenant().id(),"id",id,"title",text(i.title()),"body",text(i.body()),"category",i.categoryId(),"version",i.expectedVersion()));revision(a,id,"UPDATED","",trace);}return article(a,selected);});}
 public Object action(AuthService.Session s,UUID id,String action,Decision i,String key,UUID trace){return b.scoped(s,action.equals("publish")?"publish":"knowledge",true,a->{UUID selected=b.once(a,"knowledge."+action,key,map("id",id,"input",i),()->{var r=article(a,id);if(!Boolean.TRUE.equals(r.get("canManage")))throw ApiError.forbidden("仅作者或发布经理可管理知识");b.version(r,i.expectedVersion());String next;switch(action){case "publish"->{if(!"DRAFT".equals(r.get("status")))throw ApiError.conflict("仅草稿可发布");b.one("SELECT id FROM crm_knowledge_category WHERE tenant_id=:tenant AND id=:id AND active",map("tenant",a.tenant().id(),"id",r.get("categoryId")));next="PUBLISHED";}case "revise"->{if(!Set.of("PUBLISHED","ARCHIVED").contains(r.get("status")))throw ApiError.conflict("当前知识已经是草稿");next="DRAFT";}case "archive"->{if(text(i.reason()).isEmpty()||"ARCHIVED".equals(r.get("status")))throw ApiError.bad("归档需原因且不能重复归档");next="ARCHIVED";}default->throw ApiError.bad("知识动作无效");}b.db.update("UPDATE crm_knowledge_article SET status=:status,published_version=CASE WHEN :status='PUBLISHED' THEN version+1 ELSE published_version END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"status",next));revision(a,id,action.toUpperCase(Locale.ROOT),text(i.reason()),trace);return id;});return article(a,selected);});}
 private void revision(AuthService.Actor a,UUID id,String action,String reason,UUID trace){var r=b.one("SELECT k.*,m.display_name AS author_name,c.name AS category_name FROM crm_knowledge_article k JOIN sys_tenant_member m ON m.tenant_id=k.tenant_id AND m.id=k.author_member_id JOIN crm_knowledge_category c ON c.tenant_id=k.tenant_id AND c.id=k.category_id WHERE k.tenant_id=:tenant AND k.id=:id",map("tenant",a.tenant().id(),"id",id));b.db.update("INSERT INTO crm_knowledge_revision(id,tenant_id,article_id,business_version,action,snapshot,reason,actor_member_id,actor_name_snapshot) VALUES(:revision,:tenant,:id,:version,:action,cast(:snapshot AS jsonb),:reason,:member,:name)",map("revision",UUID.randomUUID(),"tenant",a.tenant().id(),"id",id,"version",r.get("version"),"action",action,"snapshot",b.json(r),"reason",reason,"member",a.tenant().memberId(),"name",a.tenant().memberName()));b.audit(a,"KNOWLEDGE_"+action,"KNOWLEDGE",id,number(r,"version"),trace);}
 public Object history(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return b.scoped(s,"knowledge",false,a->{var current=article(a,id);boolean privileged=privileged(a,current);var p=map("tenant",a.tenant().id(),"id",id,"privileged",privileged,"limit",size,"offset",((long)page-1)*size);String where="tenant_id=:tenant AND article_id=:id AND (:privileged OR action='PUBLISH')";return new BusinessService.Page<>(b.rows("SELECT id,business_version,action,reason,actor_name_snapshot,created_at FROM crm_knowledge_revision WHERE "+where+" ORDER BY business_version DESC LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*) FROM crm_knowledge_revision WHERE "+where,p,Long.class));});}
 public Object version(AuthService.Session s,UUID id,long version){if(version<0)throw ApiError.bad("知识版本无效");return b.scoped(s,"knowledge",false,a->version(a,id,version));}
 Map<String,Object> version(AuthService.Actor a,UUID id,long version){var current=article(a,id);var row=b.one("SELECT action,snapshot::text AS value FROM crm_knowledge_revision WHERE tenant_id=:tenant AND article_id=:id AND business_version=:version",map("tenant",a.tenant().id(),"id",id,"version",version));if(!privileged(a,current)&&!"PUBLISH".equals(row.get("action")))throw ApiError.missing();return b.object(String.valueOf(row.get("value")));}
 public Object link(AuthService.Session s,UUID ticket,Reference i,String key,UUID trace){return b.scoped(s,"ticket",true,a->{if(!a.p3Access().knowledgeRead())throw ApiError.forbidden("引用知识需知识读取权限");UUID result=b.once(a,"ticket.article",key,map("ticket",ticket,"input",i),()->{var t=desk.ticket(a,ticket);if(!Boolean.TRUE.equals(t.get("canWrite")))throw ApiError.forbidden("没有工单写入权限");b.version(t,i.expectedVersion());var k=article(a,i.articleId());if(k.get("publishedVersion")==null||"ARCHIVED".equals(k.get("status")))throw ApiError.bad("只能引用已有发布版本的知识");UUID id=UUID.randomUUID();b.db.update("INSERT INTO crm_ticket_article(id,tenant_id,ticket_id,article_id,article_version,actor_member_id) VALUES(:id,:tenant,:ticket,:article,:version,:member) ON CONFLICT(tenant_id,ticket_id,article_id,article_version) DO NOTHING",map("id",id,"tenant",a.tenant().id(),"ticket",ticket,"article",i.articleId(),"version",k.get("publishedVersion"),"member",a.tenant().memberId()));b.audit(a,"TICKET_KNOWLEDGE_LINKED","TICKET",ticket,i.expectedVersion(),trace);return ticket;});return links(a,result);});}
 private Object links(AuthService.Actor a,UUID ticket){desk.ticket(a,ticket);if(!a.p3Access().knowledgeRead())return List.of();var list=b.rows("SELECT * FROM crm_ticket_article WHERE tenant_id=:tenant AND ticket_id=:ticket ORDER BY created_at DESC,id",map("tenant",a.tenant().id(),"ticket",ticket));var result=new ArrayList<Map<String,Object>>();for(var r:list)try{var v=version(a,(UUID)r.get("articleId"),number(r,"articleVersion"));r.put("title",v.get("title"));result.add(r);}catch(ApiError ignored){}return result;}
 public Object links(AuthService.Session s,UUID ticket){return b.scoped(s,"ticket",false,a->links(a,ticket));}
}
